<div class="order-confirmation"><span class="confirmation-symbol"><?= $order['status']==='cancelled'?'×':'✓' ?></span><div class="eyebrow"><?= e($order['reference']) ?></div><h1><?= $order['status']==='completed'?'Enjoy every bite.':($order['status']==='cancelled'?'Order cancelled.':'Good things are cooking.') ?></h1><p><?= $order['status']==='cancelled'?'This order will not be prepared.':'Thank you, '.e($order['customer_name']).'. Follow your order below.' ?></p><a class="text-link" href="/orders/<?= (int)$order['id'] ?>">Refresh order status ↻</a></div>
<?php $steps=['pending'=>'Received','preparing'=>'Preparing','ready'=>'Ready']; if($order['fulfillment']==='delivery')$steps['out_for_delivery']='On the way'; $steps['completed']='Completed'; $index=array_search($order['status'],array_keys($steps),true); ?>
<?php if($order['status']!=='cancelled'): ?><ol class="order-progress"><?php $i=0; foreach($steps as $key=>$label): ?><li class="<?= $i<=$index?'done':'' ?> <?= $key===$order['status']?'active':'' ?>"><span><?= $i<$index?'✓':$i+1 ?></span><strong><?= e($label) ?></strong></li><?php $i++; endforeach; ?></ol><?php endif; ?>
<div class="two-column"><section class="panel"><div class="panel-heading"><h2>Your meal</h2><span class="status status-<?= e($order['status']) ?>"><?= e(Store::STATUSES[$order['status']]) ?></span></div><?php foreach($order['items'] as $item): ?><div class="checkout-item"><span><b><?= (int)$item['quantity'] ?>×</b> <?= e($item['name']) ?><small><?= money((int)$item['unit_price_cents']) ?> each</small></span><strong><?= money((int)$item['line_total_cents']) ?></strong></div><?php endforeach; ?><dl class="summary-lines"><div><dt>Subtotal</dt><dd><?= money((int)$order['subtotal_cents']) ?></dd></div><div><dt><?= $order['fulfillment']==='delivery'?'Delivery':'Pickup' ?></dt><dd><?= $order['delivery_fee_cents']?money((int)$order['delivery_fee_cents']):'Free' ?></dd></div><div class="summary-total"><dt>Total</dt><dd><?= money((int)$order['total_cents']) ?></dd></div></dl></section><aside class="panel"><div class="eyebrow">THE DETAILS</div><h2><?= $order['fulfillment']==='delivery'?'Coming to you':'See you soon' ?></h2><dl class="details-list"><dt>Ordered</dt><dd><?= e(displayTime((int)$order['created_at'])) ?></dd><dt>Contact</dt><dd><?= e($order['customer_name']) ?><br><?= e($order['phone']) ?></dd><?php if($order['fulfillment']==='delivery'): ?><dt>Delivery address</dt><dd class="preserve-lines"><?= e($order['address']) ?></dd><?php endif; ?><dt>Payment</dt><dd><?= $order['status']==='cancelled'?'No payment due':'Pay on '.e($order['fulfillment']) ?></dd><?php if($order['notes']): ?><dt>Your note</dt><dd class="preserve-lines"><?= e($order['notes']) ?></dd><?php endif; ?></dl><a class="text-link" href="/orders">← All your orders</a></aside></div>
